#include "simp/CodeGenerator.hpp"

#include "simp/Diagnostic.hpp"

#include <algorithm>

namespace simp {

void CodeGenerator::emitStatements(const std::vector<Statement>& statements) {
    for (const auto& statement : statements) {
        if (!blockTerminated_) emitStatement(statement);
    }
}

void CodeGenerator::emitStatement(const Statement& statement) {
    switch (statement.kind) {
    case StatementKind::Declaration: {
        const auto pointer = "%v" + std::to_string(nextVariable_++);
        scopes_.back().emplace(statement.name,
                               Binding{statement.declaredType, pointer, {}, false});
        entryAllocas_ += "  " + pointer + " = alloca " + llvmType(statement.declaredType) + "\n";
        registerRootSlot(pointer, statement.declaredType);
        if (!statement.expressions.empty()) {
            const auto value = emitExpression(*statement.expressions.front(), statement.declaredType);
            const auto converted = convertObjectValue(value, statement.declaredType,
                                                       statement.expressions.front()->location);
            instructions_ += "  store " + llvmType(statement.declaredType) + " " +
                             converted.operand + ", ptr " + pointer + "\n";
        }
        return;
    }
    case StatementKind::Assignment: {
        Binding binding;
        std::string address;
        bool arrayElementTarget = false;
        if (statement.target->kind == ExpressionKind::Identifier) {
            binding = findVariable(statement.target->value, statement.target->location);
            address = emitAddress(binding, statement.location);
        } else if (statement.target->kind == ExpressionKind::Index) {
            const auto array = emitExpression(*statement.target->left);
            const auto index =
                emitIntegerExpression(*statement.target->arguments.front());
            const auto file = internString(statement.target->location.file);
            address = newTemporary();
            instructions_ += "  " + address + " = call ptr @simp_array_index(ptr " +
                             array.operand + ", i32 " + index.operand + ", ptr " + file +
                             ", i64 " +
                             std::to_string(statement.target->location.file.size()) +
                             ", i64 " +
                             std::to_string(statement.target->location.line) + ", i64 " +
                             std::to_string(statement.target->location.column) + ")\n";
            binding.type = "any";
            arrayElementTarget = true;
        } else {
            const Expression* root = nullptr;
            const ClassDeclaration* owner = nullptr;
            std::vector<std::string> basePath;
            const bool qualified = resolveBaseQualifier(*statement.target->left, root, owner,
                                                        basePath);
            auto receiver = emitExpression(qualified ? *root : *statement.target->left);
            emitNullCheck(receiver.operand, statement.target->location);
            if (!qualified) {
                owner = classes_.at(receiver.type);
            } else {
                receiver = {owner->name,
                            emitSubobjectAddress(receiver.operand, *classes_.at(receiver.type),
                                                 basePath)};
            }
            std::vector<std::size_t> fieldPath;
            const auto* field = findField(*owner, statement.target->value, fieldPath);
            if (field == nullptr) {
                throw DiagnosticError(statement.target->location, "backend could not resolve field");
            }
            binding.type = field->type;
            address = emitFieldAddress(receiver.operand, *owner, fieldPath);
        }
        const auto value = emitExpression(*statement.expressions.front(), binding.type);
        if (arrayElementTarget) {
            emitArrayElementStore(address, value, statement.expressions.front()->location);
            return;
        }
        const auto converted = convertObjectValue(value, binding.type,
                                                   statement.expressions.front()->location);
        instructions_ += "  store " + llvmType(binding.type) + " " + converted.operand +
                         ", ptr " + address + "\n";
        return;
    }
    case StatementKind::Print:
        emitPrint(statement);
        return;
    case StatementKind::Expression:
        (void)emitExpression(*statement.expressions.front());
        return;
    case StatementKind::Return:
        if (statement.expressions.empty()) {
            emitRootFramePop();
            instructions_ += "  ret void\n";
        } else {
            const auto value = emitExpression(*statement.expressions.front(),
                                              currentMethod_->returnType);
            const auto converted = convertObjectValue(value, currentMethod_->returnType,
                                                       statement.expressions.front()->location);
            emitRootFramePop();
            instructions_ += "  ret " + llvmType(currentMethod_->returnType) + " " +
                             converted.operand + "\n";
        }
        blockTerminated_ = true;
        return;
    case StatementKind::SuperConstructorCall: {
        if (statement.virtualBaseInitializer) return;
        const auto base = classes_.find(statement.name);
        if (base == classes_.end()) {
            throw DiagnosticError(statement.location, "unknown base class '" + statement.name + "'");
        }
        const MethodDeclaration* constructor = nullptr;
        for (const auto& method : base->second->methods) {
            if (method.constructor) {
                constructor = &method;
                break;
            }
        }
        if (constructor == nullptr) return;
        const auto baseIndex = static_cast<std::size_t>(
            std::distance(currentClass_->baseClassNames.begin(),
                          std::find(currentClass_->baseClassNames.begin(),
                                    currentClass_->baseClassNames.end(), statement.name)));
        const auto basePointer = newTemporary();
        instructions_ += "  " + basePointer + " = getelementptr inbounds %Class." +
                         currentClass_->name + ", ptr %this, i32 0, i32 " +
                         std::to_string(baseIndex + 2) + "\n";
        std::string arguments = "ptr " + basePointer + ", i1 false";
        for (std::size_t index = 0; index < statement.expressions.size(); ++index) {
            const auto value = emitExpression(*statement.expressions[index],
                                              constructor->parameters[index].type);
            const auto converted = convertObjectValue(value,
                                                       constructor->parameters[index].type,
                                                       statement.expressions[index]->location);
            arguments += ", " + llvmType(constructor->parameters[index].type) + " " +
                         converted.operand;
        }
        instructions_ += "  call void " + methodSymbol(statement.name, constructor->name) +
                         "(" + arguments + ")\n";
        return;
    }
    case StatementKind::Block:
        scopes_.emplace_back();
        emitStatements(statement.body);
        scopes_.pop_back();
        return;
    case StatementKind::If: {
        const auto condition = emitIntegerExpression(*statement.expressions.front());
        const auto flag = newTemporary();
        const auto thenLabel = freshLabel("if.then");
        const auto elseLabel = freshLabel("if.else");
        const auto endLabel = freshLabel("if.end");
        instructions_ += "  " + flag + " = icmp ne i32 " + condition.operand + ", 0\n";
        instructions_ += "  br i1 " + flag + ", label %" + thenLabel + ", label %" +
                         (statement.hasAlternate ? elseLabel : endLabel) + "\n";
        instructions_ += thenLabel + ":\n";
        scopes_.emplace_back();
        blockTerminated_ = false;
        emitStatements(statement.body);
        const bool thenTerminated = blockTerminated_;
        scopes_.pop_back();
        if (!thenTerminated) instructions_ += "  br label %" + endLabel + "\n";
        bool elseTerminated = false;
        if (statement.hasAlternate) {
            instructions_ += elseLabel + ":\n";
            scopes_.emplace_back();
            blockTerminated_ = false;
            emitStatements(statement.alternate);
            elseTerminated = blockTerminated_;
            scopes_.pop_back();
            if (!elseTerminated) instructions_ += "  br label %" + endLabel + "\n";
        }
        instructions_ += endLabel + ":\n";
        blockTerminated_ = thenTerminated && statement.hasAlternate && elseTerminated;
        if (blockTerminated_) instructions_ += "  unreachable\n";
        return;
    }
    case StatementKind::While: {
        const auto conditionLabel = freshLabel("while.cond");
        const auto bodyLabel = freshLabel("while.body");
        const auto endLabel = freshLabel("while.end");
        instructions_ += "  br label %" + conditionLabel + "\n" + conditionLabel + ":\n";
        const auto condition = emitIntegerExpression(*statement.expressions.front());
        const auto flag = newTemporary();
        instructions_ += "  " + flag + " = icmp ne i32 " + condition.operand + ", 0\n";
        instructions_ += "  br i1 " + flag + ", label %" + bodyLabel + ", label %" + endLabel + "\n";
        instructions_ += bodyLabel + ":\n";
        scopes_.emplace_back();
        blockTerminated_ = false;
        emitStatements(statement.body);
        const bool bodyTerminated = blockTerminated_;
        scopes_.pop_back();
        if (!bodyTerminated) instructions_ += "  br label %" + conditionLabel + "\n";
        instructions_ += endLabel + ":\n";
        blockTerminated_ = false;
        return;
    }
    case StatementKind::Raise: {
        const auto value = emitExpression(*statement.expressions.front(), "string");
        const auto data = newTemporary();
        const auto length = newTemporary();
        const auto file = internString(statement.location.file);
        instructions_ += "  " + data + " = extractvalue %SimpleString " + value.operand +
                         ", 0\n"
                         "  " + length + " = extractvalue %SimpleString " + value.operand +
                         ", 1\n"
                         "  call void @simp_exception_raise(ptr " + data + ", i64 " + length +
                         ", ptr " + file + ", i64 " +
                         std::to_string(statement.location.file.size()) + ", i64 " +
                         std::to_string(statement.location.line) + ", i64 " +
                         std::to_string(statement.location.column) + ")\n"
                         "  unreachable\n";
        blockTerminated_ = true;
        return;
    }
    case StatementKind::Try:
        emitTry(statement);
        return;
    }
}

} // namespace simp
